pub trait Hook { fn read_impl(&mut self, input: &str) -> String; }

pub struct Reader<H: Hook> { hook: H }

impl<H: Hook> Reader<H> {
    pub fn read(&mut self, input: &str) -> String {
        let out = self.hook.read_impl(input);   // extension point
        assert!(!out.is_empty());               // invariant, written once
        out
    }
}

