pub trait Store: private::Sealed {
    fn put(&self, key: &str, value: &[u8]);        // required hook

    fn put_checked(&self, key: &str, value: &[u8]) {   // wrapper default
        assert!(!key.is_empty());
        self.put(key, value);
    }
}

mod private { pub trait Sealed {} }               // no downstream impls
